1	<?php
2	
3	require(__DIR__ . '/includes/session.php');
4	
5	$Title = __('Customer Notes');
6	$ViewTopic = 'AccountsReceivable';
7	$BookMark = 'CustomerNotes';
8	include('includes/header.php');
9	
10	include('includes/SQL_CommonFunctions.php');
11	
12	if (isset($_POST['NoteDate'])) {
13		$_POST['NoteDate'] = ConvertSQLDate($_POST['NoteDate']);
14	}
15	
16	if (isset($_GET['Id'])) {
17		$Id = (int)$_GET['Id'];
18	} elseif (isset($_POST['Id'])) {
19		$Id = (int)$_POST['Id'];
20	}
21	if (isset($_POST['DebtorNo'])) {
22		$DebtorNo = $_POST['DebtorNo'];
23	} elseif (isset($_GET['DebtorNo'])) {
24		$DebtorNo = $_GET['DebtorNo'];
25	}
26	
27	echo '<a class="toplink" href="' . $RootPath . '/SelectCustomer.php?DebtorNo=' . $DebtorNo . '">' . __('Back to Select Customer') . '</a>';
28	
29	if ( isset($_POST['submit']) ) {
30	
31		//initialise no input errors assumed initially before we test
32		$InputError = 0;
33		/* actions to take once the user has clicked the submit button
34		ie the page has called itself with some user input */
35	
36		//first off validate inputs sensible
37		if (!is_long((int)$_POST['Priority'])) {
38			$InputError = 1;
39			prnMsg( __('The contact priority must be an integer.'), 'error');
40		} elseif (mb_strlen($_POST['Note']) >200) {
41			$InputError = 1;
42			prnMsg( __('The contact\'s notes must be two hundred characters or less long'), 'error');
43		} elseif (trim($_POST['Note']) == '') {
44			$InputError = 1;
45			prnMsg( __('The contact\'s notes may not be empty'), 'error');
46		}
47	
48		if (isset($Id) and $InputError != 1) {
49	
50			$SQL = "UPDATE custnotes SET note='" . $_POST['Note'] . "',
51										date='" . FormatDateForSQL($_POST['NoteDate']) . "',
52										href='" . $_POST['Href'] . "',
53										priority='" . $_POST['Priority'] . "'
54					WHERE debtorno ='".$DebtorNo."'
55					AND noteid='".$Id."'";
56			$Msg = __('Customer Notes') . ' ' . $DebtorNo  . ' ' . __('has been updated');
57		} elseif ($InputError != 1) {
58	
59			$SQL = "INSERT INTO custnotes (debtorno,
60											href,
61											note,
62											date,
63											priority)
64					VALUES ('" . $DebtorNo. "',
65							'" . $_POST['Href'] . "',
66							'" . $_POST['Note'] . "',
67							'" . FormatDateForSQL($_POST['NoteDate']) . "',
68							'" . $_POST['Priority'] . "')";
69			$Msg = __('The contact notes record has been added');
70		}
71	
72		if ($InputError != 1) {
73			$Result = DB_query($SQL);
74					//echo '<br />' . $SQL;
75	
76			echo '<br />';
77			prnMsg($Msg, 'success');
78			unset($Id);
79			unset($_POST['Note']);
80			unset($_POST['Noteid']);
81			unset($_POST['NoteDate']);
82			unset($_POST['Href']);
83			unset($_POST['Priority']);
84		}
85	} elseif (isset($_GET['delete'])) {
86	//the link to delete a selected record was clicked instead of the submit button
87	
88	// PREVENT DELETES IF DEPENDENT RECORDS IN 'SalesOrders'
89	
90		$SQL = "DELETE FROM custnotes
91				WHERE noteid='".$Id."'
92				AND debtorno='".$DebtorNo."'";
93		$Result = DB_query($SQL);
94	
95		echo '<br />';
96		prnMsg( __('The contact note record has been deleted'), 'success');
97		unset($Id);
98		unset($_GET['delete']);
99	}
100	
101	if (!isset($Id)) {
102		$SQLname = "SELECT * FROM debtorsmaster
103					WHERE debtorno='".$DebtorNo."'";
104		$Result = DB_query($SQLname);
105		$Row = DB_fetch_array($Result);
106		echo '<p class="page_title_text"><img src="'.$RootPath.'/css/'.$Theme.'/images/maintenance.png" title="' . __('Search') . '" alt="" />' . __('Notes for Customer').': <b>' .$Row['name'] . '</b></p>';
107	
108		$SQL = "SELECT noteid,
109						debtorno,
110						href,
111						note,
112						date,
113						priority
114					FROM custnotes
115					WHERE debtorno='".$DebtorNo."'
116					ORDER BY date DESC";
117		$Result = DB_query($SQL);
118	
119		echo '<table class="selection">
120			<tr>
121				<th>' . __('Date') . '</th>
122				<th>' . __('Note') . '</th>
123				<th>' . __('WWW') . '</th>
124				<th>' . __('Priority') . '</th>
125				<th colspan="2"></th>
126			</tr>';
127	
128		while ($MyRow = DB_fetch_array($Result)) {
129			echo '<tr class="striped_row">
130					<td>', ConvertSQLDate($MyRow['date']), '</td>
131					<td>', $MyRow['note'], '</td>
132					<td><a href="', $MyRow['href'], '">', $MyRow['href'], '</a></td>
133					<td>', $MyRow['priority'], '</td>
134					<td><a href="', htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '?Id=', $MyRow['noteid'], '&DebtorNo=', $MyRow['debtorno'], '">' .  __('Edit').' </td>
135					<td><a href="', htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '?Id=', $MyRow['noteid'], '&DebtorNo=', $MyRow['debtorno'], '&delete=1" onclick="return confirm(\'' . __('Are you sure you wish to delete this customer note?') . '\');">' .  __('Delete'). '</td>
136				</tr>';
137	
138		}
139		//END WHILE LIST LOOP
140		echo '</table>';
141	}
142	if (isset($Id)) {
143		echo '<div class="centre">
144				<a href="'.htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '?DebtorNo='.$DebtorNo.'">' . __('Review all notes for this Customer') . '</a>
145			</div>';
146	}
147	
148	if (!isset($_GET['delete'])) {
149	
150		echo '<form method="post" action="' . htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '?DebtorNo=' . $DebtorNo . '">';
151		echo '<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />';
152	
153		if (isset($Id)) {
154			//editing an existing
155			echo '<p class="page_title_text"><img src="'.$RootPath.'/css/'.$Theme.'/images/maintenance.png" title="' . __('Search') . '" alt="" />' . __('Notes for Customer').': <b>' .$DebtorNo . '</b></p>';
156	
157			$SQL = "SELECT noteid,
158							debtorno,
159							href,
160							note,
161							date,
162							priority
163						FROM custnotes
164						WHERE noteid='".$Id."'
165							AND debtorno='".$DebtorNo."'";
166	
167			$Result = DB_query($SQL);
168	
169			$MyRow = DB_fetch_array($Result);
170	
171			$_POST['Noteid'] = $MyRow['noteid'];
172			$_POST['Note']	= $MyRow['note'];
173			$_POST['Href']  = $MyRow['href'];
174			$_POST['NoteDate']  = $MyRow['date'];
175			$_POST['Priority']  = $MyRow['priority'];
176			$_POST['debtorno']  = $MyRow['debtorno'];
177			echo '<input type="hidden" name="Id" value="'. $Id .'" />';
178			echo '<input type="hidden" name="Con_ID" value="' . $_POST['Noteid'] . '" />';
179			echo '<input type="hidden" name="DebtorNo" value="' . $_POST['debtorno'] . '" />';
180			echo '<fieldset>
181					<legend>', __('Edit existing customer note'), '</legend>
182					<field>
183						<label for="Noteid">' .  __('Note ID').':</label>
184						<fieldtext>' . $_POST['Noteid'] . '</fieldtext>
185					</field>';
186		} else {
187			echo '<fieldset>
188					<legend>', __('Create new customer note'), '</legend>';
189		}
190	
191		echo '<field>
192				<label for="Note">' . __('Contact Note'). '</label>';
193		if (isset($_POST['Note'])) {
194			echo '<textarea name="Note" autofocus="autofocus" required="required" rows="3" cols="32">' .$_POST['Note'] . '</textarea>
195				<fieldhelp>', __('Write the customer note here'), '</fieldhelp>
196			</field>';
197		} else {
198			echo '<textarea name="Note" autofocus="autofocus" required="required" rows="3" cols="32"></textarea>
199				<fieldhelp>', __('Write the customer note here'), '</fieldhelp>
200			</field>';
201		}
202		echo '<field>
203				<label for="Href">' .  __('WWW') . '</label>';
204		if (isset($_POST['Href'])) {
205			echo '<input type="url" name="Href" value="'.$_POST['Href'].'" size="35" maxlength="100" />
206				<fieldhelp>', __('Any website associated with this note'), '</fieldhelp>
207			</field>';
208		} else {
209			echo '<input type="url" name="Href" size="35" maxlength="100" />
210				<fieldhelp>', __('Any website associated with this note'), '</fieldhelp>
211			</field>';
212		}
213		echo '<field>
214				<label for="NoteDate">' . __('Date') . '</label>';
215		if (isset($_POST['NoteDate'])) {
216			echo '<input type="date" required name="NoteDate"  value="' . FormatDateForSQL($_POST['NoteDate']) . '" size="11" maxlength="10" />
217				<fieldhelp>', __('The date of this note'), '</fieldhelp>
218			</field>';
219		} else {
220			echo '<input type="date" required name="NoteDate" value="' . date('Y-m-d') . '" size="11" maxlength="10" />
221				<fieldhelp>', __('The date of this note'), '</fieldhelp>
222			</field>';
223		}
224		echo '<field>
225				<label for="Priority">' .  __('Priority'). '</label>';
226		if (isset($_POST['Priority'])) {
227			echo '<input type="text" class="number" required="required" name="Priority" class="number" value="' . $_POST['Priority']. '" size="1" maxlength="3" />
228				<fieldhelp>', __('The priority level for this note, between 1 and 9'), '</fieldhelp>
229			</field>';
230		} else {
231			echo '<input type="text" class="number" required="required"  name="Priority" value="1"  size="1" maxlength="3"/>
232				<fieldhelp>', __('The priority level for this note, between 1 and 9'), '</fieldhelp>
233			</field>';
234		}
235		echo '</fieldset>';
236		echo '<div class="centre">
237				<input type="submit" name="submit" value="'.__('Enter Information').'" />
238			</div>
239		</form>';
240	
241	} //end if record deleted no point displaying form to add record
242	
243	include('includes/footer.php');
244

1	 <?php
2	
3	require(__DIR__ . '/includes/session.php');
4	
5	$Title = __('Import Items');
6	$ViewTopic = 'SpecialUtilities';
7	$BookMark = basename(__FILE__, '.php');
8	include('includes/header.php');
9	
10	echo '<p class="page_title_text"><img alt="" src="' . $RootPath . '/css/' . $Theme .
11			'/images/inventory.png" title="' .
12			__('Import Stock Items from .csv') . '" />' . ' ' .
13			__('Import Stock Items from .csv') . '</p>';
14	
15	// If this script is called with a file object, then the file contents are imported
16	// If this script is called with the gettemplate flag, then a template file is served
17	// Otherwise, a file upload form is displayed
18	
19	// The CSV file must be saved in a format like the template in the import module I.E. "RECVALUE","RECVALUE2". The CSV file needs ANSI encoding for the import to work properly.
20	
21	$FieldHeadings = array(
22		'StockID',         	//  0 'STOCKID',
23		'Description',     	//  1 'DESCRIPTION',
24		'LongDescription', 	//  2 'LONGDESCRIPTION',
25		'CategoryID',      	//  3 'CATEGORYID',
26		'Units',           	//  4 'UNITS',
27		'MBFlag',          	//  5 'MBFLAG',
28		'EOQ',             	//  6 'EOQ',
29		'Discontinued',    	//  7 'DISCONTINUED',
30		'Controlled',      	//  8 'CONTROLLED',
31		'Serialised',      	//  9 'SERIALISED',
32		'Perishable',      	// 10 'PERISHABLE',
33		'Volume',          	// 11 'VOLUME',
34		'grossweight',		// 12 'grossweight',
35		'BarCode',         	// 13 'BARCODE',
36		'DiscountCategory',	// 14 'DISCOUNTCATEGORY',
37		'TaxCat',          	// 15 'TAXCAT',
38		'DecimalPlaces',   	// 16 'DECIMALPLACES',
39		'ItemPDF'          	// 17 'ITEMPDF'
40	);
41	
42	if (isset($_FILES['userfile']) and $_FILES['userfile']['name']) { //start file processing
43	
44		//initialize
45		$FieldTarget = 18;
46		$InputError = 0;
47	
48		//check file info
49		$FileName = $_FILES['userfile']['name'];
50		$TempName = $_FILES['userfile']['tmp_name'];
51		$FileSize = $_FILES['userfile']['size'];
52	
53		//get file handle
54		$FileHandle = fopen($TempName, 'r');
55	
56		//get the header row
57		$HeadRow = fgetcsv($FileHandle, 10000, ",",'"');  // Modified to handle " "" " enclosed csv - useful if you need to include commas in your text descriptions
58		// Remove UTF-8 BOM if present
59		if (substr($HeadRow[0], 0, 3) === "\xef\xbb\xbf") {
60			$HeadRow[0] = substr($HeadRow[0], 3);
61		}
62	
63		//check for correct number of fields
64		if ( count($HeadRow) != count($FieldHeadings) ) {
65			prnMsg(__('File contains '. count($HeadRow). ' columns, expected '. count($FieldHeadings). '. Try downloading a new template.'),'error');
66			fclose($FileHandle);
67			include('includes/footer.php');
68			exit();
69		}
70	
71		//test header row field name and sequence
72		$Head = 0;
73		foreach ($HeadRow as $HeadField) {
74			if ( mb_strtoupper($HeadField) != mb_strtoupper($FieldHeadings[$Head]) ) {
75				prnMsg(__('File contains incorrect headers '. mb_strtoupper($HeadField). ' != '. mb_strtoupper($FieldHeadings[$Head]). '. Try downloading a new template.'),'error');  //Fixed $FieldHeadings from $Headings
76				fclose($FileHandle);
77				include('includes/footer.php');
78				exit();
79			}
80			$Head++;
81		}
82	
83		//start database transaction
84		DB_Txn_Begin();
85	
86		//loop through file rows
87		$Row = 1;
88		while ( ($MyRow = fgetcsv($FileHandle, 10000, ",")) !== false ) {
89	
90			//check for correct number of fields
91			$FieldCount = count($MyRow);
92			if ($FieldCount != $FieldTarget){
93				prnMsg(__($FieldTarget. ' fields required, '. $FieldCount. ' fields received'),'error');
94				fclose($FileHandle);
95				include('includes/footer.php');
96				exit();
97			}
98	
99			// cleanup the data (csv files often import with empty strings and such)
100			$StockID = mb_strtoupper($MyRow[0]);
101			foreach ($MyRow as &$Value) {
102				$Value = trim($Value);
103			}
104	
105			//first off check if the item already exists
106			$SQL = "SELECT COUNT(stockid) FROM stockmaster WHERE stockid='".$StockID."'";
107			$Result = DB_query($SQL);
108			$testrow = DB_fetch_row($Result);
109			if ($testrow[0] != 0) {
110				$InputError = 1;
111				prnMsg(__('Stock item '. $StockID. ' already exists'),'error');
112			}
113	
114			//next validate inputs are sensible
115			if (!$MyRow[1] or mb_strlen($MyRow[1]) > 50 OR mb_strlen($MyRow[1])==0) {
116				$InputError = 1;
117				prnMsg(__('The stock item description must be entered and be fifty characters or less long') . '. ' . __('It cannot be a zero length string either') . ' - ' . __('a description is required'). ' ("'. implode('","',$MyRow). $stockid. '") ','error');
118			}
119			if (mb_strlen($MyRow[2])==0) {
120				$InputError = 1;
121				prnMsg(__('The stock item description cannot be a zero length string') . ' - ' . __('a long description is required'),'error');
122			}
123			if (mb_strlen($StockID) ==0) {
124				$InputError = 1;
125				prnMsg(__('The Stock Item code cannot be empty'),'error');
126			}
127			if (ContainsIllegalCharacters($StockID) OR mb_strstr($StockID,' ')) {
128				$InputError = 1;
129				prnMsg(__('The stock item code cannot contain any of the following characters') . " ' & + \" \\ " . __('or a space'). " (". $StockID. ")",'error');
130				$StockID='';
131			}
132			if (mb_strlen($MyRow[4]) >20) {
133				$InputError = 1;
134				prnMsg(__('The unit of measure must be 20 characters or less long'),'error');
135			}
136			if (mb_strlen($MyRow[13]) >20) {
137				$InputError = 1;
138				prnMsg(__('The barcode must be 20 characters or less long'),'error');
139			}
140			if ($MyRow[10]!=0 AND $MyRow[10]!=1) {
141				$InputError = 1;
142				prnMsg(__('Values in the Perishable field must be either 0 (No) or 1 (Yes)') ,'error');
143			}
144			if (!is_numeric($MyRow[11])) {
145				$InputError = 1;
146				prnMsg(__('The volume of the packaged item in cubic metres must be numeric') ,'error');
147			}
148			if ($MyRow[11] <0) {
149				$InputError = 1;
150				prnMsg(__('The volume of the packaged item must be a positive number'),'error');
151			}
152			if (!is_numeric($MyRow[12])) {
153				$InputError = 1;
154				prnMsg(__('The weight of the packaged item in KGs must be numeric'),'error');
155			}
156			if ($MyRow[12]<0) {
157				$InputError = 1;
158				prnMsg(__('The weight of the packaged item must be a positive number'),'error');
159			}
160			if (!is_numeric($MyRow[6])) {
161				$InputError = 1;
162				prnMsg(__('The economic order quantity must be numeric'),'error');
163			}
164			if ($MyRow[6] <0) {
165				$InputError = 1;
166				prnMsg(__('The economic order quantity must be a positive number'),'error');
167			}
168			if ($MyRow[8]==0 AND $MyRow[9]==1){
169				$InputError = 1;
170				prnMsg(__('The item can only be serialised if there is lot control enabled already') . '. ' . __('Batch control') . ' - ' . __('with any number of items in a lot/bundle/roll is enabled when controlled is enabled') . '. ' . __('Serialised control requires that only one item is in the batch') . '. ' . __('For serialised control') . ', ' . __('both controlled and serialised must be enabled'),'error');
171			}
172	
173			$mbflag = $MyRow[5];
174			if ($mbflag!='M' and $mbflag!='K' and $mbflag!='A' and $mbflag!='B' and $mbflag!='D' and $mbflag!='G') {
175				$InputError = 1;
176				prnMsg(__('Items must be of MBFlag type Manufactured(M), Assembly(A), Kit-Set(K), Purchased(B), Dummy(D) or Phantom(G)'),'error');
177			}
178			if (($mbflag=='A' OR $mbflag=='K' OR $mbflag=='D' OR $mbflag=='G') AND $MyRow[8]==1){
179				$InputError = 1;
180				prnMsg(__('Assembly/Kitset/Phantom/Service items cannot also be controlled items') . '. ' . __('Assemblies, Dummies and Kitsets are not physical items and batch/serial control is therefore not appropriate'),'error');
181			}
182			if ($MyRow[3]==''){
183				$InputError = 1;
184				prnMsg(__('There are no inventory categories defined. All inventory items must belong to a valid inventory category,'),'error');
185			}
186			if ($MyRow[17]==''){
187				$InputError = 1;
188				prnMsg(__('ItemPDF must contain either a filename, or the keyword `none`'),'error');
189			}
190	
191			if ($InputError !=1){
192				if ($MyRow[9]==1){ /*Not appropriate to have several dp on serial items */
193					$MyRow[16]=0;
194				}
195	
196				//attempt to insert the stock item
197				$SQL = "
198					INSERT INTO stockmaster (
199						stockid,
200						description,
201						longdescription,
202						categoryid,
203						units,
204						mbflag,
205						eoq,
206						discontinued,
207						controlled,
208						serialised,
209						perishable,
210						volume,
211						grossweight,
212						barcode,
213						discountcategory,
214						taxcatid,
215						decimalplaces)
216					VALUES (
217						'$StockID',
218						'" . $MyRow[1]	. "',
219						'" . $MyRow[2]	. "',
220						'" . $MyRow[3]	. "',
221						'" . $MyRow[4]	. "',
222						'" . $MyRow[5]	. "',
223						"  . $MyRow[6]	. ",
224						"  . $MyRow[7]	. ",
225						"  . $MyRow[8]	. ",
226						"  . $MyRow[9]	. ",
227						"  . $MyRow[10]	. ",
228						"  . $MyRow[11]	. ",
229						"  . $MyRow[12]	. ",
230						'" . $MyRow[13]	. "',
231						'" . $MyRow[14]	. "',
232						"  . $MyRow[15]	. ",
233						"  . $MyRow[16]	. "
234					);
235				";
236	
237				$ErrMsg =  __('The item could not be added because');
238				$Result = DB_query($SQL, $ErrMsg);
239	
240				if (DB_error_no() ==0) { //the insert of the new code worked so bang in the stock location records too
241	
242					$SQL = "INSERT INTO locstock (loccode,
243													stockid)
244										SELECT locations.loccode,
245										'" . $StockID . "'
246										FROM locations";
247	
248					$ErrMsg =  __('The locations for the item') . ' ' . $StockID .  ' ' . __('could not be added because');
249					$InsResult = DB_query($SQL, $ErrMsg);
250	
251					if (DB_error_no() ==0) {
252						prnMsg( __('New Item') .' ' . $StockID  . ' '. __('has been added to the transaction'),'info');
253					} else { //location insert failed so set some useful error info
254						$InputError = 1;
255						prnMsg(__($InsResult),'error');
256					}
257	
258				} else { //item insert failed so set some useful error info
259					$InputError = 1;
260					prnMsg(__($InsResult),'error');
261				}
262	
263			}
264	
265			if ($InputError == 1) { //this row failed so exit loop
266				break;
267			}
268	
269			$Row++;
270	
271		}
272	
273		if ($InputError == 1) { //exited loop with errors so rollback
274			prnMsg(__('Failed on row '. $Row. '. Batch import has been rolled back.'),'error');
275			DB_Txn_Rollback();
276		} else { //all good so commit data transaction
277			DB_Txn_Commit();
278			prnMsg( __('Batch Import of') .' ' . $FileName  . ' '. __('has been completed. All transactions committed to the database.'),'success');
279		}
280	
281		fclose($FileHandle);
282	
283	} elseif ( isset($_POST['gettemplate']) || isset($_GET['gettemplate']) ) { //download an import template
284	
285		echo '<br /><br /><br />"'. implode('","',$FieldHeadings). '"<br /><br /><br />';
286	
287	} else { //show file upload form
288	
289		echo '
290			<br />
291			<a href="' . $RootPath . '/Z_ImportStocks.php?gettemplate=1">Get Import Template</a>
292			<br />
293			<br />';
